import CarouselBlock from '@/components/pro/CarouselBlock'
import ProCoinList from '@/components/pro/ProCoinList'
import ProTopBlock from '@/components/pro/ProTopBlock'
import useProListStore from '@/store/pro/list'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Box, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

export type porListType = {
  label: 'Liquidity' | 'Volume (24H)' | 'Price/% Δ'
  value: 'liquidity' | 'volume' | 'change'
}

function Pro() {
  const [refreshTrigger, setRefreshTrigger] = useState(0)
  const { isShowTokenRickModal, setIsOpenProTokenRiskModal } = useProListStore()

  const { isApp } = useWindowWidth()
  const handleRefresh = () => {
    setRefreshTrigger(prev => prev + 1)
  }

  // 1分钟自动刷新
  useEffect(() => {
    if (isShowTokenRickModal) {
      setIsOpenProTokenRiskModal(true)
    }
    const intervalId = setInterval(() => {
      handleRefresh()
    }, 60 * 1000)

    return () => clearInterval(intervalId)
  }, [])

  return (
    <VStack w="100%" align="flex-start" gap="0px">
      <CarouselBlock
        containerProps={{ w: isApp ? 'calc(100% + 24px)' : 'calc(100% + 40px)', ml: isApp ? '-12px' : '-20px', mb: isApp ? '12px' : '0' }}
      />
      <VStack w="100%" gap="0px">
        <Box borderTop="1px solid" borderColor={isApp ? 'transparent' : 'border'} w={{ base: '100%', lg: '1160px' }} margin="auto" pb="16px">
          <ProTopBlock handleRefresh={handleRefresh} isApp={isApp} />
        </Box>
        <ProCoinList refreshTrigger={refreshTrigger} />
      </VStack>
    </VStack>
  )
}

export default Pro
